const ALLY_SACERDOTE_RESERVED = 'data:image/png;base64,';
const ENEMY_GOBLIN_CHAMAN = 'data:image/png;base64,';
const PLAYER_PESADA = 'data:image/png;base64,';
const ENEMY_JEFE_GOBLIN = 'data:image/png;base64,';
const PLAYER_TIRADOR = 'data:image/png;base64,';
const PLAYER_DOBLEFILO = 'data:image/png;base64,';
const ENEMY_GOBLIN_GUERRERO = 'data:image/png;base64,';
const ENEMY_GOBLIN_ARQUERO = 'data:image/png;base64,';
const ENEMY_GOBLIN_SAQUEADOR = 'data:image/png;base64,';
const PLAYER_MAGO = 'data:image/png;base64,';
const ENEMY_OGRO = 'data:image/png;base64,';
const ENEMY_HOBGOBLIN = 'data:image/png;base64,';
const ENEMY_GILGOBLIN = 'data:image/png;base64,';
// Paladín y Hechicero (2026-10-02): derivados a mano de los sprites de
// Guerrero y Asesino (mismo cuerpo/estilo) — yelmo y escudo plateados con
// cruz dorada para el Paladín; túnica púrpura, ojos verdes y bastón con
// orbe para el Hechicero.
const PLAYER_PALADIN = 'data:image/png;base64,';
const PLAYER_HECHICERO = 'data:image/png;base64,';
export const CLASS_SPRITES = { pesada: PLAYER_PESADA, tirador: PLAYER_TIRADOR, doblefilo: PLAYER_DOBLEFILO, mago: PLAYER_MAGO, paladin: PLAYER_PALADIN, hechicero: PLAYER_HECHICERO };
// Los aliados reclutables no tienen un dibujo propio por personaje (igual que
// en el prototipo): se dibujan con el sprite de su rol de combate, los mismos
// 5 que ya existen para el jugador — Aldric (guerrero) usa el mismo sprite
// que un Guerrero jugador, etc. Sacerdote no es una senda jugable, así que
// ese sprite (ya generado en su momento para el prototipo) queda reservado
// únicamente para este uso.
export const ALLY_SPRITES = { guerrero: PLAYER_PESADA, arquero: PLAYER_TIRADOR, asesino: PLAYER_DOBLEFILO, mago: PLAYER_MAGO, sacerdote: ALLY_SACERDOTE_RESERVED };
export const ENEMY_SPRITES = { goblin_guerrero: ENEMY_GOBLIN_GUERRERO, goblin_saqueador: ENEMY_GOBLIN_SAQUEADOR, goblin_arquero: ENEMY_GOBLIN_ARQUERO, jefe_goblin: ENEMY_JEFE_GOBLIN, goblin_chaman: ENEMY_GOBLIN_CHAMAN, hobgoblin: ENEMY_HOBGOBLIN, gilgoblin: ENEMY_GILGOBLIN, ogro: ENEMY_OGRO };

// Variantes por raza (2026-10-02): cada clase con rasgos de la raza elegida
// (Bárbaro: piel curtida, pintura de guerra y pelaje; Enano: más bajo y con
// barba; Hada: alas y orejas; Dracónido: escamas, cuernos y cola; Hombre
// bestia: pelaje, orejas y cola). Humano usa el sprite base de la clase.
export const RACE_SPRITES = {
  pesada: { barbaro:'data:image/png;base64,', enano:'data:image/png;base64,', hada:'data:image/png;base64,', draconido:'data:image/png;base64,', bestia:'data:image/png;base64,' },
  tirador: { barbaro:'data:image/png;base64,', enano:'data:image/png;base64,', hada:'data:image/png;base64,', draconido:'data:image/png;base64,', bestia:'data:image/png;base64,' },
  doblefilo: { barbaro:'data:image/png;base64,', enano:'data:image/png;base64,', hada:'data:image/png;base64,', draconido:'data:image/png;base64,', bestia:'data:image/png;base64,' },
  mago: { barbaro:'data:image/png;base64,', enano:'data:image/png;base64,', hada:'data:image/png;base64,', draconido:'data:image/png;base64,', bestia:'data:image/png;base64,' },
  paladin: { barbaro:'data:image/png;base64,', enano:'data:image/png;base64,', hada:'data:image/png;base64,', draconido:'data:image/png;base64,', bestia:'data:image/png;base64,' },
  hechicero: { barbaro:'data:image/png;base64,', enano:'data:image/png;base64,', hada:'data:image/png;base64,', draconido:'data:image/png;base64,', bestia:'data:image/png;base64,' },
};
export function playerSpriteFor(style, race){
  return (RACE_SPRITES[style] && RACE_SPRITES[style][race]) || CLASS_SPRITES[style] || null;
}
